entries[158731] = { ["name"] = "Blutverderbnisaura", ["text"] = "Sofort\nUk'urogg wurde durch Maraks dunkle Blutmagie so verderbt, dass er jetzt böse Energie ausstrahlt.\n\nDiese Energie führt dazu, dass sich unter allen Spielercharakteren an Bord des Schlachtschiffes in regelmäßigen Abständen eine Pfütze aus verderbtem Blut bildet, solange er am Leben ist." }
